import{c as t,Q as n,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"End-of-event checklist","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/end-of-event-checklist.md","filePath":"user/after-the-event/end-of-event-checklist.md"}'),s={name:"user/after-the-event/end-of-event-checklist.md"};function o(i,e,h,l,d,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="end-of-event-checklist" tabindex="-1">End-of-event checklist <a class="header-anchor" href="#end-of-event-checklist" aria-label="Permalink to &quot;End-of-event checklist&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers wrapping up after the competition.</p><p>A printable checklist of what to do once the last competitor has finished or been accounted for. Each item links to the page that explains it.</p><h2 id="before-anyone-leaves-the-venue" tabindex="-1">Before anyone leaves the venue <a class="header-anchor" href="#before-anyone-leaves-the-venue" aria-label="Permalink to &quot;Before anyone leaves the venue&quot;">​</a></h2><p><strong>Everyone accounted for</strong></p><ul><li>[ ] The dashboard&#39;s <strong>On course</strong> count is zero, or everyone still on it is known about. See <a href="./../running-the-event/safety-check">Safety check: accounting for everyone</a>.</li><li>[ ] Read the <strong>Start</strong>, <strong>Check</strong> and <strong>Finish</strong> stations&#39; memories if anyone is unaccounted for: a runner who punched the finish but never downloaded shows up there. See <a href="./../running-the-event/safety-check#reading-sportident-stations">Reading SportIdent stations</a>.</li><li>[ ] The <strong>Pending</strong> count is zero: every radio finish has had its card downloaded. See <a href="./../running-the-event/who-is-still-on-course">Who is still on course</a>.</li></ul><p><strong>Every result settled</strong></p><ul><li>[ ] Sort out disputed results and missing punches on the competitor. See <a href="./results#when-a-result-is-disputed">When a result is disputed</a> and <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a>.</li><li>[ ] Mark the non-starters <strong>DNS</strong>: <strong>Competitors → Actions → Set competitors DNS…</strong> does a whole class at once.</li><li>[ ] Anyone still out who has been seen on course: <strong>Overtime</strong> or <strong>DNF</strong>.</li></ul><p><strong>Finish</strong></p><ul><li>[ ] Click <strong>Finish event</strong>. If anyone is still unsettled, <strong>Event not finalised</strong> lists them with the buttons that settle them. It won&#39;t finish past a radio finish whose card hasn&#39;t been read. See <a href="./results#settling-everyone-first">Settling everyone first</a>.</li></ul><p><strong>Hire items</strong></p><ul><li>[ ] Collect every hire card and lent item: filter the <strong>Hire items</strong> screen to <strong>Out</strong> to see who still has one. See <a href="./../running-the-event/hire-items">Hire items</a>.</li></ul><p><strong>Publish</strong></p><ul><li>[ ] Upload the results to Eventor: <strong>Results → Publish → Upload to Eventor</strong>. See <a href="./exports#uploading-to-eventor">Uploading to Eventor</a>.</li><li>[ ] Export any files your federation or another system needs. See <a href="./exports">Exporting data</a>.</li><li>[ ] Print or pin up the results, and the prize-giving list. See <a href="./results#prize-giving-and-the-results-board">Prize-giving and the results board</a>.</li></ul><p><strong>Keep a copy</strong></p><ul><li>[ ] Take a backup: <strong>Backup event → Download</strong> on the event&#39;s card, and keep it somewhere other than the server computer. See <a href="./../reference/backup-and-restore">Backup and restore</a>.</li><li>[ ] Take the external backup drive with you.</li><li>[ ] If cameras recorded anything worth keeping, copy the recordings off the server: they are not in the backup. The <strong>Video</strong> section of the <strong>Screens</strong> page names the folder. See <a href="./../screens/info-screens#what-is-recorded-and-what-is-not">What is recorded, and what is not</a>.</li></ul><blockquote><p><strong>Note:</strong> Finishing the event isn&#39;t final. If a competitor turns up afterwards, even the next day, open the event and click <strong>Restart event</strong> to take it live again, download their card, and finish it again. Upload the results again afterwards. See <a href="./../running-the-event/dashboard#restarting-an-event-you-ve-already-finished">Restarting an event you&#39;ve already finished</a>.</p></blockquote><h2 id="back-at-home" tabindex="-1">Back at home <a class="header-anchor" href="#back-at-home" aria-label="Permalink to &quot;Back at home&quot;">​</a></h2><ul><li>[ ] Upload or export the results if you couldn&#39;t at the venue, and upload again after any correction.</li><li>[ ] If cloud sync is on, check the event has published. Its card on the Events list shows a cloud with a tick once it&#39;s on the cloud. See <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing to the meshO cloud</a>.</li><li>[ ] For a series or a carnival, carry today&#39;s new cards and class changes into the next event with the <a href="./changes-report">changes report</a>.</li><li>[ ] Return borrowed hire cards to their owners, using each card&#39;s <strong>Owner</strong> in <strong>Settings → Hire card registry</strong>.</li><li>[ ] Note anything that went wrong on the day, and what fixed it, for next time. The <a href="./../reference/audit-trail">audit trail</a> shows what was changed and when.</li><li>[ ] Shut the server computer down if it isn&#39;t a permanent installation: <strong>Quit</strong> from the tray or menu bar first.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./results">Results</a></li><li><a href="./exports">Exporting data</a></li><li><a href="./../reference/backup-and-restore">Backup and restore</a></li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li><li><a href="./changes-report">Changes report</a></li></ul>',21)])])}const f=t(s,[["render",o]]);export{g as __pageData,f as default};
